    spec = Path("SPEC.md")
    if not spec.exists():
        fail("SPEC.md not found")

    content = spec.read_text()

    required_sections = [
        "Summary",
        "Requirements",
        "Failure modes",
        "Non-functional",
        "Out of scope",
    ]
    missing = [s for s in required_sections if s.lower() not in content.lower()]
